	"golive__tip_broadcaster_1": "<b>İPUCU:</b> Canlı yayına geçtiğin için teşekkürler! İnsanlar yayınına katılmaya başladığında onlara bir “merhaba” ile hoş geldin de.",
	"golive__tip_broadcaster_10": "\"<b>İPUCU:</b> X'te canlı yayına geçtiğin için teşekkürler! ≺3\"",
	"golive__tip_broadcaster_2": "<b>İPUCU:</b> İnsanlar, canlı video yayınına katıldığında onlara isimleriyle hitap etmeyi dene. Bu, onları heyecanlandırır!",
	"golive__tip_broadcaster_3": "<b>İPUCU:</b> İnsanların seni bulmasını kolaylaştırmak için en az birkaç dakika canlı yayında kaldığından emin ol.",
	"golive__tip_broadcaster_4": "<b>İPUCU:</b> İzleyicilerine nereli olduklarını sor. Bu, ortamı ısıtmanın en iyi yoludur.",
	"golive__tip_broadcaster_5": "<b>İPUCU:</b> Katıldıkları için insanlara teşekkür et ve izleyenleri yayında tutmak amacıyla yorumlarını yanıtla.",
	"golive__tip_broadcaster_6": "<b>İPUCU:</b> Canlı yayına geçtiğin sırada bağlantın kesilirse, daha iyi çeken bir yerden yayınına kaldığın yerden devam edebilirsin.",
	"golive__tip_broadcaster_7": "<b>İPUCU:</b> Bir dahaki sefere canlı yayına geçtiğinde bildirim almaları için insanlardan seni takip etmelerini iste.",
	"golive__tip_broadcaster_8": "<b>İPUCU:</b> Canlı video yayınına “merhaba” diyerek başla. Daha sonra izleyen insanlar bundan hoşlanacaktır.",
	"golive__tip_broadcaster_9": "<b>İPUCU:</b> Canlı video yayınını sonlandırmadan önce izledikleri için insanlara teşekkür et.",
	"golive__tip_pre_broadcast_1": "<b>İPUCU:</b> İnsanların videonu keşfetmesine yardımcı olmak için canlı yayına geçmeden önce bir başlık yaz.",
	"golive__tip_pre_broadcast_2": "<b>İPUCU:</b> Açıklayıcı bir başlık, insanların hangi konuda canlı video yayını yaptığını bilmesine daha iyi yardımcı olur.",
	"golive__tip_pre_broadcast_3": "<b>İPUCU:</b> Fikre mi ihtiyacın var? Etrafı gezdir, yeteneğini paylaş veya ilgini çeken bir şeyler hakkında sohbet et.",
	"golive__tip_pre_broadcast_4": "<b>İPUCU:</b> Canlı yayına geçmeden önce telefon çekim gücünün yüksek olduğundan emin ol.",
	"golive__tip_pre_broadcast_5": "<b>İPUCU:</b> İnsanların canlı videonu keşfetmesine yardımcı olmak için başlığına bir etiket ekle.",
	"golive__tip_pre_broadcast_6": "\"<b>İPUCU:</b> Şu anda bu kadar ipucu sunabiliyoruz. X'te canlı yayına geçtiğin için teşekkürler!\"",
