	"identity_education_conditions": "\"X ve Au10tix'in, kimliğimi doğrulamak ve taklitçiliği önlemek gibi, X'in ilgili güvenlik ve emniyet amaçları için biyometrik veriler de dahil olmak üzere kimliğimin ve selfie'min görüntülerini kullanmasına izin veriyorum. Au10tix bu verileri 30 güne kadar saklayabilir. {{}}Daha fazla bilgi al{{}}\"",
	"identity_education_conditions_age_verification": "\"X ve Persona'nın yaşımı onaylamak amacıyla kimliğimi ve fotoğrafımı kullanmasını kabul ediyorum. Fotoğrafınız saklanmaz. X ve xAI, yaş bilgilerinizi saklayabilir. {{}}Daha fazla bilgi al{{}}\"",
	"identity_education_conditions_eea": "\"X'in kimliğimi doğrulamak amacıyla biyometrik veriler de dâhil olmak üzere kimlik görüntülerimi ve profilimdeki kişisel verileri Au10tix ile paylaşmasına izin veriyorum.\nAyrıca, X'in biyometrik veriler de dâhil olmak üzere kimlik görüntülerimi 30 güne kadar saklamasına ve taklitçiliği önlemek de dâhil olmak üzere emniyet ve güvenlik amacıyla bunları ve profilimdeki verileri kullanmasına izin veriyorum. {{}}Daha fazla bilgi al{{}}\"",
	"identity_education_conditions_persona_vendor": "\"X ve Persona'nın, kimliğimi doğrulamak ve X'in ilgili güvenlik ve emniyet, sahtecilik önleme ve ödeme amaçları için ayıklanan biyometrik veriler de dahil olmak üzere kimliğimin ve selfie'min görüntülerini kullanmasına izin veriyorum. Persona bu verileri 30 güne kadar saklayabilir. X; tam adımı, adresimi ve karma işlemi uygulanmış belge kimlik numaramı X Premium hizmetine abone olduğum sürece saklayabilir. {{}}Daha fazla bilgi al{{}}\"",
