	"payment_funds_insurance_footer_secondary_text": "FDIC sigortası ve hesap sahipliği kategorileri hakkında daha fazla bilgiyi ﻿burada﻿ bulabilirsin.",
	"payment_funds_insurance_footer_text": "\"Mevduatların FDIC Üyesi Cross River Bank tarafından tutulmaktadır ve bankada bulunan her hesap sahipliği kategorisindeki tüm hesaplar FDIC tarafından bireysel ve tüzel kişi başına 250.000 $'a kadar sigortalıdır (toplamda); buna temsilci sıfatıyla tutulan hesaplar da dahildir.\"",
	"payment_funds_insurance_footer_text_format": "Mevduatların, FDIC üyesi Cross River Bank (\\\"Banka\\\") tarafından tutulmaktadır ve Bankada tutulan her bir hesap, mülkiyet kategorisindeki tüm hesaplar (birleşik olarak) FDIC tarafından bireysel ve tüzel kişi başına {amount} tutarına kadar sigortalıdır; buna temsilci sıfatıyla tutulan hesaplar da dahildir.",
