	"profile_smart_blocked_autoblocked_by_twitter_description": "\"@%1$sadlı kullanıcının gönderilerini görüntülemen ve onlarla etkileşim kurman geçici bir süreliğine otomatik olarak engellendi. Bu durum, kullanıcının Güvenli Modda olması ve etkileşimlerini taciz veya spam içerebilecek içerik olarak işaretlememiz nedeniyle meydana geldi.\n\nOtomatik engellemelerin her zaman doğru olmayabileceğini biliyoruz, bu nedenle algılama sistemimizi iyileştirmek için çalışmalarımıza devam ediyoruz.\n\n{{}}Güvenli%2$sMod%2$snedir{{}}?\n\nİşte sohbetlerini sağlıklı tutmanın ve otomatik olarak engellenmekten kaçınmanın yolları.\"",
