	"ps__tip_broadcaster_1": "<b>İPUCU:</b> Yayın yaptığın için teşekkürler! Katılan kişilere merhaba demeyi unutma.",
	"ps__tip_broadcaster_11": "\"<b>İPUCU:</b> Scope'ta yayın başlattığın için teşekkürler! ≺3\"",
	"ps__tip_broadcaster_2": "<b>İPUCU:</b> Katılan izleyicilere isimleriyle seslenmeyi dene; bu onları heyecanlandırır!",
	"ps__tip_broadcaster_3": "<b>İPUCU:</b> İnsanların seni bulmasını kolaylaştırmak için en az birkaç dakika yayında olman gerekir.",
	"ps__tip_broadcaster_4": "<b>İPUCU:</b> İzleyicilerine nereden katıldıklarını sormak ortamı ısıtmanın en iyi yoludur.",
	"ps__tip_broadcaster_5": "<b>İPUCU:</b> Katıldıkları için izleyicilere teşekkür et ve etkileşimi canlı tutmak amacıyla yorumlarını yanıtla.",
	"ps__tip_broadcaster_6": "<b>İPUCU:</b> Yayın sırasında bağlantı kesilirse, daha iyi çeken bir yerden canlı yayına geçebilirsin.",
	"ps__tip_broadcaster_7": "<b>İPUCU:</b> Canlı yayına geçtiğin zaman bildirim almaları için izleyicilerinden seni takip etmelerini iste.",
	"ps__tip_broadcaster_8": "<b>İPUCU:</b> Yayınını başlatır başlatmaz merhaba de. Bu, tekrar gösterim izleyicilerinin hoşuna gidecektir.",
	"ps__tip_broadcaster_9": "<b>İPUCU:</b> Yayınını sonlandırmadan önce yayınını izledikleri için izleyicilerine teşekkür et.",
	"ps__tip_pre_broadcast_1": "<b>İPUCU:</b> Yayınını başlatmadan önce bir başlık yaz ve benzer ilgi alanlarına sahip insanlarla tanış!",
	"ps__tip_pre_broadcast_2": "<b>İPUCU:</b> Açıklayıcı bir başlık, insanların hangi konuda yayın yaptığını bilmesine yardımcı olur.",
	"ps__tip_pre_broadcast_3": "<b>İPUCU:</b> Fikre mi ihtiyacın var? Etrafı gezdir, yeteneğini paylaş veya ilgini çeken bir konu hakkında konuş.",
	"ps__tip_pre_broadcast_4": "<b>İPUCU:</b> Canlı yayına geçmeden önce telefon çekim gücünün yüksek olduğundan emin ol.",
	"ps__tip_pre_broadcast_5": "\"<b>İPUCU:</b> Daha fazla izleyiciye ulaşmak için yayınını X'te paylaş.\"",
	"ps__tip_pre_broadcast_6": "<b>İPUCU:</b> Takip ettiğin ve aynı zamanda seni takip eden kişilere özel yayın yapabilirsin.",
	"ps__tip_pre_broadcast_8": "<b>İPUCU:</b> İnsanların yayınını keşfetmesine yardımcı olmak için başlığına yayının konusuyla alakalı bir etiket ekle.",
	"ps__tip_pre_broadcast_9": "<b>İPUCU:</b> Şu anda bu kadar ipucu sunabiliyoruz, Scope kullandığın için teşekkürler!",
	"ps__tip_viewer_1": "<b>İPUCU:</b> İlk katılanlardan birisin, bir yorum yaz ve merhaba de!",
