	"tipjar_input_rationale_kakao_pay": "\"Kullanıcılar, yukarıya girdiğin QR Bağlantısına bahşiş gönderecek.\nQR Bağlantını ekleyerek veya bahşiş kabul ederek ismin, e-posta adresin ve diğer bilgilerin dahil olmak üzere ödeme hizmetiyle paylaşılan kişisel bilgilerini ortaya çıkarıyor olabilirsin.\n\nKakaoPay QR Bağlantısı; KakaoTalk More > Sağ Üstteki Tarayıcı > Para Kodu > Pano Görseli Simgesi altında bulunabilir. Bağlantıyı panona kopyalamak için simgeye dokun ve bağlantıyı yukarıya yapıştır.\"",
	"tipjar_input_rationale_paytm": "Kullanıcılar, yukarıya girdiğin Paytm bağlantılı cep telefonu numarasına bahşiş gönderecek. Cep telefonu numaranı ekleyerek ve bahşiş kabul ederek ismin, e-posta adresin, telefon numaran ve diğer bilgilerin dahil olmak üzere, ödeme hizmetiyle paylaşılan kişisel bilgilerini ortaya çıkarıyor olabilirsin.",
